1	// See hybrid.hpp. Builds the ROI Trigger from the CLI, resolving pc boundaries.
2	#include "hybrid.hpp"
3	
4	#include "elf_syms.hpp"
5	
6	namespace andes_sim {
7	
8	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
9	                       std::string& err) {
10	  err.clear();
11	  const std::string kind = cli.trigger.empty() ? "marker" : cli.trigger;
12	
13	  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params
14	
15	  if (kind == "pc") {
16	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
17	      err = "trigger pc requires --pc-start and --pc-end "
18	            "(a symbol name or 0x address)";
19	      return {};
20	    }
21	    std::string e1, e2;
22	    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
23	    if (!e1.empty()) { err = e1; return {}; }
24	    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
25	    if (!e2.empty()) { err = e2; return {}; }
26	    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
27	    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
28	    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
29	  }
30	
31	  if (kind == "simpoint") {
32	    err = "trigger simpoint is not yet supported (F11)";
33	    return {};
34	  }
35	
36	  err = "unknown trigger '" + kind + "' (want marker|pc)";
37	  return {};
38	}
39	
40	std::string hybrid_hw_check(const EngineDescriptor& acc) {
41	  if (acc.xlen != 0 && acc.xlen != 64)
42	    return "engine " + acc.id + " is rv" + std::to_string(acc.xlen) +
43	           " (xlen=" + std::to_string(acc.xlen) +
44	           "); the hybrid fast leg (QEMU) is rv64-only";
45	  return "";
46	}
47	
48	std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
49	                                         std::string& err) {
50	  err.clear();
51	  std::vector<std::string> out;
52	
53	  // kanata ROI visualization first (marker/pc only; objdump rides kanata).
54	  if (!cli.kanata.empty()) {
55	    if (kind != "marker" && kind != "pc") {
56	      err = "--kanata is only supported with trigger marker or pc (got " + kind +
57	            ")";
58	      return {};
59	    }
60	    out.push_back("--kanata");
61	    out.push_back(cli.kanata);
62	    out.push_back("--kanata-roi");
63	    if (!cli.objdump.empty()) {
64	      out.push_back("--objdump");
65	      out.push_back(cli.objdump);
66	    }
67	  } else if (!cli.objdump.empty()) {
68	    err = "--objdump requires --kanata";
69	    return {};
70	  }
71	
72	  // Warmup window last (any trigger; 0/absent contributes nothing).
73	  if (!cli.vsim_warmup_icount.empty() && cli.vsim_warmup_icount != "0") {
74	    out.push_back("--vsim-warmup-icount");
75	    out.push_back(cli.vsim_warmup_icount);
76	  }
77	  return out;
78	}
79	
80	}  // namespace andes_sim
