1	// Unit tests for the andesim CLI parser (parse_cli).
2	//
3	// Plain assert-and-count harness (no doctest dependency on the driver side).
4	// Exits non-zero if any check fails. Run by tests/andes_sim/test_andes_sim_f1.sh
5	// and, later, the F5+ infra tests.
6	#include <string>
7	#include <vector>
8	
9	#include "cli.hpp"
10	#include "test_check.hpp"
11	
12	using andes_sim::Cli;
13	using andes_sim::parse_cli;
14	
15	int main() {
16	  // Selection axes, space-separated form.
17	  {
18	    Cli c = parse_cli({"run", "--mode", "fast", "--engine",
19	                       "vsim:ax45mpv_premium", "--trigger", "marker",
20	                       "prog.elf"});
21	    CHECK(c.error.empty());
22	    CHECK(c.subcommand == "run");
23	    CHECK(c.model == "fast");
24	    CHECK(c.engine == "vsim:ax45mpv_premium");
25	    CHECK(c.trigger == "marker");
26	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
27	    CHECK(!c.has_passthrough);
28	    CHECK(c.passthrough.empty());
29	  }
30	
31	  // Selection axes, --flag=value form.
32	  {
33	    Cli c = parse_cli({"run", "--mode=cycle", "--engine=vsim:x"});
34	    CHECK(c.error.empty());
35	    CHECK(c.model == "cycle");
36	    CHECK(c.engine == "vsim:x");
37	  }
38	
39	  // The `--` boundary: everything after it is verbatim passthrough, even
40	  // tokens that look like framework flags (they must NOT be parsed).
41	  {
42	    Cli c = parse_cli({"run", "--mode", "fast", "prog.elf", "--", "-gdb",
43	                       "tcp::1234", "-S", "--mode", "IGNORED"});
44	    CHECK(c.error.empty());
45	    CHECK(c.model == "fast");
46	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
47	    CHECK(c.has_passthrough);
48	    CHECK(c.passthrough.size() == 5);
49	    CHECK(c.passthrough[0] == "-gdb");
50	    CHECK(c.passthrough[1] == "tcp::1234");
51	    CHECK(c.passthrough[4] == "IGNORED");
52	  }
53	
54	  // A `--` with nothing after it still marks passthrough (empty argv).
55	  {
56	    Cli c = parse_cli({"run", "--mode", "fast", "--"});
57	    CHECK(c.error.empty());
58	    CHECK(c.has_passthrough);
59	    CHECK(c.passthrough.empty());
60	  }
61	
62	  // Per-subcommand help.
63	  {
64	    Cli c = parse_cli({"run", "-h"});
65	    CHECK(c.subcommand == "run");
66	    CHECK(c.help);
67	  }
68	  {
69	    Cli c = parse_cli({"list", "--help"});
70	    CHECK(c.subcommand == "list");
71	    CHECK(c.help);
72	  }
73	
74	  // Top-level help: no subcommand.
75	  {
76	    Cli c = parse_cli({"-h"});
77	    CHECK(c.subcommand.empty());
78	    CHECK(c.help);
79	  }
80	
81	  // list positional target.
82	  {
83	    Cli c = parse_cli({"list", "fixtures"});
84	    CHECK(c.subcommand == "list");
85	    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
86	  }
87	
88	  // Hybrid pc-trigger boundaries (symbol + 0x address), space-separated form.
89	  {
90	    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "pc",
91	                       "--pc-start", "main", "--pc-end", "0x80001234",
92	                       "prog.elf"});
93	    CHECK(c.error.empty());
94	    CHECK(c.pc_start == "main");
95	    CHECK(c.pc_end == "0x80001234");
96	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
97	  }
98	
99	  // Hybrid mem size + warmup; mixes space and =forms.
100	  // --mmap-size is the retired spelling, kept as a hidden alias of --mem-size.
101	  {
102	    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "marker",
103	                       "--mmap-size=64M", "--vsim-warmup-icount", "500",
104	                       "prog.elf"});
105	    CHECK(c.error.empty());
106	    CHECK(c.mem_size == "64M");
107	    CHECK(c.vsim_warmup_icount == "500");
108	  }
109	
110	  // --qemu-icount / --vsim-icount were removed with the icount trigger: each
111	  // is now an unknown option (the warmup knob --vsim-warmup-icount stays).
112	  {
113	    Cli c = parse_cli({"run", "--mode", "hybrid", "--qemu-icount", "10",
114	                       "prog.elf"});
115	    CHECK(!c.error.empty());
116	    Cli d = parse_cli({"run", "--mode", "hybrid", "--vsim-icount", "10",
117	                       "prog.elf"});
118	    CHECK(!d.error.empty());
119	  }
120	
121	  // --mem-size is the documented spelling (works on every model).
122	  {
123	    Cli c = parse_cli({"run", "--mode", "fast", "--mem-size", "2G",
124	                       "prog.elf"});
125	    CHECK(c.error.empty());
126	    CHECK(c.mem_size == "2G");
127	  }
128	
129	  // Absent hybrid flags stay empty -- cmd_run supplies the real defaults.
130	  {
131	    Cli c = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
132	    CHECK(c.error.empty());
133	    CHECK(c.pc_start.empty());
134	    CHECK(c.mem_size.empty());
135	  }
136	
137	  // kanata/objdump pass-through flags parse like the rest (space + =form).
138	  {
139	    Cli c = parse_cli({"run", "--mode", "hybrid", "--kanata", "k.txt",
140	                       "--objdump=o.txt", "prog.elf"});
141	    CHECK(c.error.empty());
142	    CHECK(c.kanata == "k.txt");
143	    CHECK(c.objdump == "o.txt");
144	  }
145	
146	  // --verify is a boolean (oracle differential verification), default off.
147	  {
148	    Cli c = parse_cli({"run", "--mode", "hybrid", "--verify", "prog.elf"});
149	    CHECK(c.error.empty());
150	    CHECK(c.verify);
151	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
152	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
153	    CHECK(!d.verify);
154	  }
155	
156	  // --cosim is a boolean (checkpoint co-simulation), default off;
157	  // --cosim-interval carries the checkpoint spacing as a string.
158	  {
159	    Cli c = parse_cli({"run", "--mode", "hybrid", "--cosim",
160	                       "--cosim-interval", "500", "prog.elf"});
161	    CHECK(c.error.empty());
162	    CHECK(c.cosim);
163	    CHECK(c.cosim_interval == "500");
164	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
165	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
166	    CHECK(!d.cosim);
167	    CHECK(d.cosim_interval.empty());
168	  }
169	
170	  // --gdb is a boolean, default off; valid on fast and cycle.
171	  {
172	    Cli c = parse_cli({"run", "--mode", "fast", "--gdb", "prog.elf"});
173	    CHECK(c.error.empty());
174	    CHECK(c.gdb);
175	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
176	    Cli d = parse_cli({"run", "--mode", "cycle", "prog.elf"});
177	    CHECK(!d.gdb);
178	  }
179	
180	  // Unknown option before `--` is an error.
181	  {
182	    Cli c = parse_cli({"run", "--bogus"});
183	    CHECK(!c.error.empty());
184	  }
185	
186	  // A selection flag with no value is an error.
187	  {
188	    Cli c = parse_cli({"run", "--mode"});
189	    CHECK(!c.error.empty());
190	  }
191	
192	  // --model was renamed to --mode (clean break): the old spelling no longer
193	  // parses -- it falls through to the unknown-option error.
194	  {
195	    Cli c = parse_cli({"run", "--model", "fast", "prog.elf"});
196	    CHECK(!c.error.empty());
197	  }
198	
199	  return andes_sim::test::report("cli parse");
200	}
