1	// Unit tests for hybrid_trigger (F9): CLI selection -> ROI Trigger, including
2	// pc-boundary resolution against a real fixture's .symtab and the icount
3	// defaults. Pure (no spawn). rt_pc_jump.elf defines `phase_b_landing` (0x100042)
4	// and `phase_c` (0x100046). Plain assert-and-count harness.
5	#include <string>
6	#include <vector>
7	
8	#include "cli.hpp"
9	#include "engine_descriptor.hpp"
10	#include "hybrid.hpp"
11	#include "plan.hpp"
12	#include "repo_root.hpp"
13	#include "test_check.hpp"
14	
15	using namespace andes_sim;
16	using andes_sim::test::check_eq;
17	
18	namespace {
19	Cli mk(const std::vector<std::string>& args) { return parse_cli(args); }
20	}  // namespace
21	
22	int main() {
23	  const std::string elf =
24	      (repo_root() / "tests" / "fixtures" / "rt_pc_jump.elf").string();
25	
26	  // --- hybrid_hw_check: ISA sync guard -- the fast leg (QEMU) is rv64 ---
27	  {
28	    EngineDescriptor d;  // an rv32 engine (e.g. vsim:d23) cannot pair with it
29	    d.id = "vsim:d23";
30	    d.xlen = 32;
31	    const std::string err = hybrid_hw_check(d);
32	    CHECK(!err.empty());
33	    CHECK(err.find("vsim:d23") != std::string::npos);
34	    CHECK(err.find("rv64") != std::string::npos);
35	  }
36	  {
37	    EngineDescriptor d;  // matching xlen passes
38	    d.id = "vsim:ax45mpv_premium";
39	    d.xlen = 64;
40	    CHECK(hybrid_hw_check(d).empty());
41	  }
42	  {
43	    EngineDescriptor d;  // an engine that reports no xlen is accepted as-is
44	    d.id = "vsim:x";
45	    CHECK(hybrid_hw_check(d).empty());
46	  }
47	
48	  // No --trigger defaults to marker (the repo's documented default), no params.
49	  {
50	    std::string err;
51	    Trigger t = hybrid_trigger(mk({"run", "--mode", "hybrid"}), elf, err);
52	    CHECK(err.empty());
53	    CHECK(t.kind == "marker");
54	    CHECK(t.params.empty());
55	  }
56	
57	  // pc: a symbol start and a 0x end both resolve; stored as 0x-prefixed hex.
58	  {
59	    std::string err;
60	    Trigger t = hybrid_trigger(
61	        mk({"run", "--mode", "hybrid", "--trigger", "pc", "--pc-start",
62	            "phase_b_landing", "--pc-end", "0x100046"}),
63	        elf, err);
64	    CHECK(err.empty());
65	    CHECK(t.kind == "pc");
66	    CHECK(t.params.at("enter_pc") == "0x100042");
67	    CHECK(t.params.at("exit_pc") == "0x100046");
68	  }
69	
70	  // pc requires both boundaries.
71	  {
72	    std::string err;
73	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
74	                       "--pc-start", "phase_b_landing"}),
75	                   elf, err);
76	    CHECK(!err.empty());
77	  }
78	
79	  // pc with an undefined symbol is an error naming the symbol.
80	  {
81	    std::string err;
82	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
83	                       "--pc-start", "nope_sym", "--pc-end", "phase_c"}),
84	                   elf, err);
85	    CHECK(!err.empty());
86	    CHECK(err.find("nope_sym") != std::string::npos);
87	  }
88	
89	  // icount was removed as a user trigger: it now reports as an unknown trigger,
90	  // not a silent fallback. (The icount measurement mechanism survives in the
91	  // plan layer for the SimPoint pipeline; it is just no longer CLI-selectable.)
92	  {
93	    std::string err;
94	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "icount"}), elf,
95	                   err);
96	    CHECK(!err.empty());
97	  }
98	
99	  // simpoint is not wired yet (F11) -- a clear error, not a silent marker fallback.
100	  {
101	    std::string err;
102	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "simpoint"}),
103	                   elf, err);
104	    CHECK(!err.empty());
105	  }
106	
107	  // An unknown trigger is an error.
108	  {
109	    std::string err;
110	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "bogus"}), elf,
111	                   err);
112	    CHECK(!err.empty());
113	  }
114	
115	  // --- vsim_extra_args: user-forwarded vsim-leg flags, validated by trigger ---
116	  {
117	    std::string err;
118	    // warmup only -- valid for any trigger.
119	    check_eq(vsim_extra_args(
120	                 mk({"run", "--mode", "hybrid", "--vsim-warmup-icount", "50"}),
121	                 "pc", err),
122	             {"--vsim-warmup-icount", "50"}, "warmup");
123	    CHECK(err.empty());
124	    // a 0 (or absent) warmup contributes nothing.
125	    CHECK(vsim_extra_args(
126	              mk({"run", "--mode", "hybrid", "--vsim-warmup-icount", "0"}),
127	              "marker", err)
128	              .empty());
129	    CHECK(err.empty());
130	    CHECK(vsim_extra_args(mk({"run", "--mode", "hybrid"}), "marker", err).empty());
131	    CHECK(err.empty());
132	
133	    // kanata (marker/pc): --kanata <f> --kanata-roi.
134	    check_eq(
135	        vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata", "k.txt"}),
136	                        "marker", err),
137	        {"--kanata", "k.txt", "--kanata-roi"}, "kanata");
138	    CHECK(err.empty());
139	    // kanata + objdump.
140	    check_eq(vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata",
141	                                 "k.txt", "--objdump", "o.txt"}),
142	                             "pc", err),
143	             {"--kanata", "k.txt", "--kanata-roi", "--objdump", "o.txt"},
144	             "kanata-objdump");
145	    CHECK(err.empty());
146	    // kanata THEN warmup -- the e2e.sh ordering.
147	    check_eq(vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata",
148	                                 "k.txt", "--vsim-warmup-icount", "9"}),
149	                             "marker", err),
150	             {"--kanata", "k.txt", "--kanata-roi", "--vsim-warmup-icount", "9"},
151	             "kanata-warmup");
152	    CHECK(err.empty());
153	
154	    // --kanata is marker/pc only -- rejected under any other kind.
155	    vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata", "k.txt"}),
156	                    "simpoint", err);
157	    CHECK(!err.empty());
158	    // --objdump requires --kanata.
159	    vsim_extra_args(mk({"run", "--mode", "hybrid", "--objdump", "o.txt"}),
160	                    "marker", err);
161	    CHECK(!err.empty());
162	  }
163	
164	  return andes_sim::test::report("hybrid");
165	}
